package com.example.demo; import com.example.demo.model.User; import com.example.demo.repository.UserRepository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.data.domain.*; @SpringBootTest class UserPaginationTest { @Autowired UserRepository r; @BeforeEach void seed(){r.deleteAll(); for(String n:new String[]{"Ananya Sen","Bhavana Reddy","Deepak Verma","Rahul Kumar","Vijay Sharma"}) r.save(new User(n,n.toLowerCase().replace(" ",".")+"@aditya.edu.in"));} @Test void pagination(){Pageable p=PageRequest.of(0,3,Sort.by("name").ascending()); Page<User> page=r.findAll(p); System.out.println("Total Elements: "+page.getTotalElements()); System.out.println("Total Pages: "+page.getTotalPages()); page.forEach(u->System.out.println(u));} }